// DB is up: remember chat id in workflow static data so alerts still work when Postgres is down.
const e = $('Normalize error').first().json;
const db = $json;
const stat = $getWorkflowStaticData('global');
if (db.chat_id) stat.chatId = db.chat_id;
const suppressAfter = Number(db.suppress_after ?? 3);
const recent = Number(db.recent_similar ?? 0);
return [{ json: buildAlert(e, { chatId: db.chat_id || stat.chatId, errorId: db.error_id,
  send: !e.is_subworkflow && recent < suppressAfter, lastBeforeSuppress: recent === suppressAfter - 1, windowMin: db.window_min }) }];

function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function buildAlert(e, o) {
  const lines = [
    `🔴 <b>${esc(e.workflow_name)}</b>`,
    `Node: <code>${esc(e.node_name || '—')}</code>`,
    `Error: <code>${esc(e.error_message.slice(0, 700))}</code>`,
    e.execution_url ? `Execution: <a href="${esc(e.execution_url)}">#${esc(e.execution_id)}</a>` : 'Execution: — (trigger error)',
    ...(e.sub_execution_url ? [`Sub-execution: <a href="${esc(e.sub_execution_url)}">#${esc(e.sub_execution_id)}</a>`] : []),
    o.errorId ? `errors.id = ${o.errorId}` : '⚠️ not logged: Postgres unavailable',
  ];
  if (o.lastBeforeSuppress) lines.push(`🔕 Further alerts for this node are muted for ${o.windowMin} min (still logged).`);
  return { chat_id: o.chatId, text: lines.join('\n'), send: o.send && !!o.chatId };
}

// Postgres failed: fall back to the chat id cached in static data by a previous successful run.
const e = $('Normalize error').first().json;
const stat = $getWorkflowStaticData('global');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = [
  `🔴 <b>${esc(e.workflow_name)}</b>`,
  `Node: <code>${esc(e.node_name || '—')}</code>`,
  `Error: <code>${esc(e.error_message.slice(0, 700))}</code>`,
  e.execution_url ? `Execution: <a href="${esc(e.execution_url)}">#${esc(e.execution_id)}</a>` : 'Execution: —',
  ...(e.sub_execution_url ? [`Sub-execution: <a href="${esc(e.sub_execution_url)}">#${esc(e.sub_execution_id)}</a>`] : []),
  `⚠️ not logged: Postgres unavailable (${esc(String($json.error?.message ?? $json.message ?? '').slice(0, 200))})`,
].join('\n');
return [{ json: { chat_id: stat.chatId, text, send: !!stat.chatId && !e.is_subworkflow } }];

// Error Trigger has two shapes: a failed execution, or a failed trigger node (no execution id/url).
const d = $json;
const ex = d.execution || {};
const err = ex.error || (d.trigger && d.trigger.error) || {};
// A failed sub-workflow surfaces twice: in its own execution (mode "integrated") and in the parent.
// Only the parent alerts; it carries a link to the sub-execution where the failing node is.
const isSub = ex.mode === 'integrated';
const subId = err.executionId && String(err.executionId) !== String(ex.id) ? String(err.executionId) : null;
const subUrl = subId && err.workflowId && ex.url
  ? ex.url.replace(/\/workflow\/[^/]+\/executions\/[^/]+$/, `/workflow/${err.workflowId}/executions/${subId}`) : null;
return [{ json: {
  is_subworkflow: isSub,
  sub_execution_id: subId,
  sub_execution_url: subUrl,
  workflow_id: d.workflow?.id ?? null,
  workflow_name: d.workflow?.name ?? 'unknown',
  execution_id: ex.id ?? null,
  execution_url: ex.url ?? null,
  node_name: ex.lastNodeExecuted ?? err.node?.name ?? d.trigger?.node?.name ?? null,
  error_message: String(err.message ?? 'unknown error').slice(0, 2000),
  error_stack: err.stack ? String(err.stack).slice(0, 8000) : null,
  context: { mode: ex.mode ?? d.trigger?.mode ?? null, retryOf: ex.retryOf ?? null, sub_execution_id: subId,
             description: err.description ?? null, httpCode: err.httpCode ?? null },
}}];
